// Strategy to use when merging changesets with conflicting changes.
type ChangesetMergeConflict = core.ChangesetMergeConflict

const (
	// Attempt the merge and fail if git merge fails due to conflicts
	ChangesetMergeConflictFail ChangesetMergeConflict = core.ChangesetMergeConflictFail

	// Fail before attempting merge if file-level conflicts are detected
	ChangesetMergeConflictFailEarly ChangesetMergeConflict = core.ChangesetMergeConflictFailEarly

	// Let git create conflict markers in files. For modify/delete conflicts, keeps the modified version. Fails on binary conflicts.
	ChangesetMergeConflictLeaveConflictMarkers ChangesetMergeConflict = core.ChangesetMergeConflictLeaveConflictMarkers

	// The conflict is resolved by applying the version of the calling changeset
	ChangesetMergeConflictPreferOurs ChangesetMergeConflict = core.ChangesetMergeConflictPreferOurs

	// The conflict is resolved by applying the version of the other changeset
	ChangesetMergeConflictPreferTheirs ChangesetMergeConflict = core.ChangesetMergeConflictPreferTheirs
)

// Strategy to use when merging multiple changesets with git octopus merge.
type ChangesetsMergeConflict = core.ChangesetsMergeConflict

const (
	// Attempt the octopus merge and fail if git merge fails due to conflicts
	ChangesetsMergeConflictFail ChangesetsMergeConflict = core.ChangesetsMergeConflictFail

	// Fail before attempting merge if file-level conflicts are detected between any changesets
	ChangesetsMergeConflictFailEarly ChangesetsMergeConflict = core.ChangesetsMergeConflictFailEarly
)

